from collections import Counter
def sub(a,b): return tuple(x-y for x,y in zip(a,b))
def dot(a,b): return sum(x*y for x,y in zip(a,b))
def cross(a,b): return (a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0])
exact_vertices=[[tuple(Fraction(x) for x in v) for v in o['vertices']] for o in geometry['objects']]
panels=[]
for index,obj in enumerate(geometry['objects']):
    vertices=exact_vertices[index]; triangles=obj['triangles']
    if len(vertices)!=4 or len(set(vertices))!=4 or len(triangles)!=2: continue
    normals=[cross(sub(vertices[t[1]],vertices[t[0]]),sub(vertices[t[2]],vertices[t[0]])) for t in triangles]
    if not dot(normals[0],normals[0]) or dot(normals[0],normals[1])<=0: continue
    if any(dot(sub(vertex,vertices[0]),normals[0])!=0 for vertex in vertices): continue
    edge_counts=Counter(tuple(sorted((t[k],t[(k+1)%3]))) for t in triangles for k in range(3))
    boundary=[edge for edge,count in edge_counts.items() if count==1]
    if len(boundary)!=4 or sorted(edge_counts.values())!=[1,1,1,1,2]: continue
    adjacency={vertex:[] for vertex in range(4)}
    for first,second in boundary: adjacency[first].append(second); adjacency[second].append(first)
    if any(len(neighbors)!=2 for neighbors in adjacency.values()): continue
    if any(dot(sub(vertices[neighbors[0]],vertices[vertex]),sub(vertices[neighbors[1]],vertices[vertex]))!=0 for vertex,neighbors in adjacency.items()): continue
    panels.append(index)
print('validated panels',panels)
def clip_axis(polygon,axis,bound,sign):
    output=[]
    if not polygon: return output
    for previous,current in zip(polygon[-1:]+polygon[:-1],polygon):
        prev_value=sign*(previous[axis]-bound); curr_value=sign*(current[axis]-bound)
        if (prev_value<0)!=(curr_value<0):
            proportion=prev_value/(prev_value-curr_value)
            output.append(tuple(previous[k]+proportion*(current[k]-previous[k]) for k in range(2)))
        if curr_value>=0: output.append(current)
    return output
def area2(polygon):
    return abs(sum(first[0]*second[1]-first[1]*second[0] for first,second in zip(polygon,polygon[1:]+polygon[:1])))
checks={}
for camera in cameras['views']:
    direction=tuple(Fraction(x) for x in camera['direction_rational']); view=camera['name']
    for index in panels:
        vertices=exact_vertices[index]
