        clip=(np.array(camera['projection_matrix'])@np.array(camera['view_matrix'])@homogeneous.T).T
        ndc=clip[:,:3]/clip[:,3,None]
        inside=bool(np.all(np.abs(ndc)<=1+1e-12))
        blockers=[]
        for other_index,other in enumerate(geometry['objects']):
