            other_vertices=exact_vertices[other_index]
            if not any(vertex[2]>0 for vertex in other_vertices): continue
            assert all(vertex[2]>0 for vertex in other_vertices)
            projected=[(vertex[0]-vertex[2]*direction[0]/direction[2],vertex[1]-vertex[2]*direction[1]/direction[2]) for vertex in other_vertices]
            for triangle in other['triangles']:
                polygon=[projected[k] for k in triangle]
